import heapq

def match(orders):
    trades = []
    buy_heap = []   # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}       # id -> {'side', 'price', 'qty', 'active'}
    seq_counter = 0

    def clean_buy_top():
        while buy_heap:
            neg_price, seq, oid = buy_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return buy_heap[0]
        return None

    def clean_sell_top():
        while sell_heap:
            price, seq, oid = sell_heap[0]
            o = book.get(oid)
            if o is None or not o['active'] or o['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return sell_heap[0]
        return None

    for order in orders:
        otype = order[0]

        if otype == 'cancel':
            _, oid = order
            o = book.get(oid)
            if o is not None and o['active'] and o['qty'] > 0:
                o['active'] = False
            continue

        if otype == 'limit':
            _, oid, side, price, qty = order
        elif otype == 'ioc':
            _, oid, side, price, qty = order
        elif otype == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                top = clean_sell_top()
                if top is None:
                    break
                s_price, s_seq, s_id = top
                if price is not None and s_price > price:
                    break
                s_order = book[s_id]
                trade_qty = min(remaining, s_order['qty'])
                trades.append([oid, s_id, s_price, trade_qty])
                remaining -= trade_qty
                s_order['qty'] -= trade_qty
                if s_order['qty'] <= 0:
                    s_order['active'] = False
                    heapq.heappop(sell_heap)
            if otype == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'active': True}
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
                seq_counter += 1
            # ioc/market discard remainder

        else:  # side == 'sell'
            while remaining > 0:
                top = clean_buy_top()
                if top is None:
                    break
                neg_price, b_seq, b_id = top
                b_price = -neg_price
                if price is not None and b_price < price:
                    break
                b_order = book[b_id]
                trade_qty = min(remaining, b_order['qty'])
                trades.append([b_id, oid, b_price, trade_qty])
                remaining -= trade_qty
                b_order['qty'] -= trade_qty
                if b_order['qty'] <= 0:
                    b_order['active'] = False
                    heapq.heappop(buy_heap)
            if otype == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'active': True}
                heapq.heappush(sell_heap, (price, seq_counter, oid))
                seq_counter += 1
            # ioc/market discard remainder

    return trades

